module max_ranks(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] a_0, a_1,\n    input wire [31:0] b_0, b_1,\n    input wire [31:0] K,\n    output reg [1:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n\n    reg [1:0] state;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 2'd0;\n            cycle_count <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= COMPUTE;\n                    end\n                end\n                COMPUTE: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if ((a_0 + K < a_1 && b_1 + K < b_0) || (a_1 + K < a_0 && b_0 + K < b_1)) begin\n                        result <= 2'd1;\n                    end else begin\n                        result <= 2'd2;\n                    end\n                    state <= DONE_STATE;\n                end\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule